package com.hoteluq.model;
import java.time.LocalDate;import java.util.*;
public class PointsAccount {private final List<PointsLot> lots=new ArrayList<>();public void earn(int points,LocalDate date){if(points>0)lots.add(new PointsLot(points,date));}public int available(LocalDate date){return lots.stream().filter(l->l.isValid(date)).mapToInt(PointsLot::getRemaining).sum();}public void redeem(int points,LocalDate date){if(points<=0||available(date)<points)throw new IllegalStateException("Puntos insuficientes o vencidos");int left=points;for(PointsLot lot:lots.stream().filter(l->l.isValid(date)).sorted(Comparator.comparing(PointsLot::getExpires)).toList()){int take=Math.min(left,lot.getRemaining());lot.consume(take);left-=take;if(left==0)break;}}public List<PointsLot> getLots(){return List.copyOf(lots);}}
